/** @jsxImportSource react */

import { cn } from '@videojs/utils/style';
import type { ReactNode } from 'react';

import { Container as ContainerPrimitive } from '../../skin-primitives';
import { ErrorDialog } from '../shared/skins/compat/shared/error-dialog';
import { StatusAnnouncer } from '../shared/skins/compat/shared/status-announcer';
import { LivePlaybackHotkeys } from '../shared/skins/shared/behaviors/live-playback-hotkeys';
import { LiveAudioControls } from './controls';

export interface LiveAudioSkinProps extends Omit<ContainerPrimitive.Props, 'children'> {
  children?: ReactNode;
}

export function LiveAudioSkin({ children, className, ...props }: LiveAudioSkinProps = {}) {
  return (
    <ContainerPrimitive
      className={cn('media-skin', 'media-container', 'media-audio', className)}
      data-theme="compat"
      data-preset="live-audio"
      {...props}
    >
      {children}
      <ErrorDialog />
      <LiveAudioControls />

      <LivePlaybackHotkeys />
      <StatusAnnouncer />
    </ContainerPrimitive>
  );
}
